def l1Witness : List Nat := [0, 1, 4, 6]
def l1PairSums : List Nat := [0, 1, 2, 4, 5, 6, 7, 8, 10, 12]
def l1FragmentCheck : Bool := decide (l1Witness.Nodup ∧ l1Witness.length = 4 ∧ l1Witness.head? = some 0 ∧ l1Witness.getLast? = some 6 ∧ l1PairSums.Nodup ∧ l1PairSums.length = 10)
